window.TADABBUR_SAD = {"_meta":{"description":"تدبّر سورة ص (٣٨) — سورةٌ مكّيّةٌ محورُها إثباتُ التوحيدِ والرسالة، وتسليةُ النبيِّ ﷺ بقصصِ الأنبياءِ الصابرين، والتذكيرُ بالبعثِ والجزاء. تفتتح بالقسمِ بالقرآنِ ذي الذكر، وتعجُّبِ المشركين من دعوةِ التوحيد، ثم قصصُ داودَ وخصومتِه وتوبتِه، وسليمانَ وفتنتِه وأوبتِه، وأيوبَ وصبرِه، وذكرُ إبراهيمَ وإسحاقَ ويعقوبَ وإسماعيلَ واليسعَ وذي الكفل، ثم مشهدُ الجنّةِ لأهلها والنارِ لأهلها، وخصومةُ أهلِ النار، وقصةُ آدمَ وإباءِ إبليسَ وطردِه واستنظارِه، وختامُ السورةِ بأنّ القرآنَ ذكرٌ للعالمين.","honesty":"كلُّ وقفةٍ مُسنَدةٌ إلى تفسيرٍ معتمد (ابن كثير/السعدي) وموسومةٌ بدرجتها. حالُ القلبِ والعملُ اجتهاديٌّ موسوم. لا يُقدَّم شيءٌ على أنه إعجازٌ مثبت."},"n":38,"name":"ص","total_ayahs":88,"audio":[],"passages":[{"title":"القسمُ بالقرآنِ، وكِبرُ الكافرين وعجبُهم من التوحيد، وعجزُهم عن معارضةِ الله","range":[1,11],"theme":"القسمُ بالقرآنِ ذي الذكر، وأنّ سببَ كفرِ الكافرين الكِبرُ والشقاقُ لا خفاءُ الحق، والتخويفُ بهلاكِ القرونِ الماضيةِ حين لا مناص، وعجبُهم من دعوةِ التوحيدِ وتواصيهم على الثباتِ على آلهتهم، واعتراضُهم على اختصاصِ النبيِّ بالوحيِ حسدًا، وبيانُ أنّ خزائنَ الرحمةِ ومُلكَ السماواتِ بيدِ الله وحده، وأنهم جندٌ مهزوم","verses":[{"n":1,"reflection":{"text":"«ص والقرآن ذي الذكر» — أقسم الله بالقرآنِ ذي الذكرِ والشرفِ والتذكيرِ على صدقِ الرسالة؛ ففي هذا تعظيمُ شأنِ القرآنِ وأنه ذكرٌ وشرف؛ فعظّم القرآنَ في قلبك، واجعله ذكرك وشرفك، فالقرآنُ ذكرٌ لمن تذكّر به، وشرفٌ لمن تمسّك به، فاعتنِ به تلاوةً وتدبّرًا وعملًا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ القرآنِ واتّخاذُه ذكرًا وشرفًا."},"action":{"text":"عظّم القرآنَ في قلبك، فقد أقسم الله به ووصفه بأنه «ذو الذكر» أي ذو الشرفِ والتذكير «ص والقرآن ذي الذكر»؛ فالقرآنُ ذكرٌ يذكّرك بربك وبالآخرةِ وبما ينفعك، وشرفٌ لك ولأمّتك؛ فاجعله ذكرك في يومك: اتلُه بتدبّر، وتذكّر به عند الغفلة، وتشرّف بحمله والعملِ به؛ فمن اعتنى بالقرآنِ رفعه الله، ومن أعرض عنه وضعه؛ فاجعل لك وردًا يوميًّا من تلاوته وتدبّره؛ فالقرآنُ حبلُ الله المتين، والذكرُ الحكيم؛ فتشرّف بصحبته، واستكثر من ذكرِ الله به؛ فبه تحيا القلوب، وتُنال السعادةُ في الدارين."}},{"n":2,"reflection":{"text":"«بل الذين كفروا في عزة وشقاق» — بل الذين كفروا في تكبّرٍ عن الحقِّ وحميّةٍ جاهليةٍ ومخالفةٍ وعداوةٍ للنبيّ؛ ففي هذا بيانُ أنّ سببَ كفرهم الكِبرُ لا خفاءُ الحق؛ فاحذر الكِبرَ عن قبولِ الحقّ، فإنه أصلُ الكفرِ والصدود، فتواضع للحقِّ واقبله ممّن جاء به، فالكِبرُ يمنع من الهداية.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الكِبرِ عن قبولِ الحقّ، فهو أصلُ الصدود."},"action":{"text":"احذر الكِبرَ عن قبولِ الحقّ، فإنّ الله بيّن أنّ سببَ كفرِ الكافرين ليس خفاءَ الحقِّ ولا ضعفَ الحجّة، بل الكِبرُ والحميّةُ والمخالفةُ والعداوة «بل الذين كفروا في عزة وشقاق»؛ فما منعهم من الإيمانِ إلا استكبارهم عن الحقِّ وشقاقهم للنبيّ؛ فالكِبرُ أعظمُ حاجبٍ عن الهداية؛ فتواضع للحقِّ، واقبله ممّن جاء به ولو كان صغيرًا أو دونك؛ فالكِبرُ بطرُ الحقِّ وغمطُ الناس؛ فلا يدخل الجنّةَ من كان في قلبه مثقالُ ذرّةٍ من كبر؛ فطهّر قلبك من الكِبرِ والعناد؛ واقبل الحقَّ بانقيادٍ وتواضع؛ فمن تواضع للحقِّ رفعه الله وهداه، ومن استكبر عنه أضلّه الله وأرداه؛ فاجعل قلبك منقادًا للحقِّ، خاضعًا له، لا مستكبرًا معاندًا."}},{"n":3,"reflection":{"text":"«كم أهلكنا من قبلهم من قرن فنادوا ولات حين مناص» — كثيرٌ من الأممِ أهلكناهم قبل هؤلاء، فنادوا واستغاثوا حين نزل العذابُ، ولا وقتَ نجاةٍ ولا مهرب؛ ففي هذا التخويفُ بعاقبةِ المكذّبين وأنّ التوبةَ لا تنفع عند العذاب؛ فبادر بالتوبةِ في وقتها، فلا تنفع التوبةُ حين نزولِ العذاب، فاغتنم مهلةَ الحياةِ قبل فواتِ الأوان.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ بالتوبةِ قبل نزولِ العذاب، فلا مناصَ حينئذ."},"action":{"text":"اعتبر بعاقبةِ الأممِ الكثيرةِ التي أهلكها الله قبل هؤلاء المكذّبين، فلمّا نزل بهم العذابُ نادوا واستغاثوا وتابوا، ولكن لا وقتَ نجاةٍ ولا مهربٍ ولا فوت «كم أهلكنا من قبلهم من قرن فنادوا ولات حين مناص»؛ فالتوبةُ لا تنفع عند معاينةِ العذاب؛ فبادر بالتوبةِ في وقتها المقبول، قبل أن ينزل بك العذابُ أو يحضرك الموت؛ فاغتنم مهلةَ الحياةِ والصحّةِ للتوبةِ والعمل؛ فمن سوّف بالتوبةِ حتى نزل العذابُ لم تنفعه؛ فلا تؤخّر التوبةَ، فإنّ الأجلَ قد يأتي بغتة؛ فتب إلى الله الآن، واعمل صالحًا قبل فواتِ الأوان؛ فالسعيدُ من بادر بالتوبةِ في زمنِ الإمهال؛ فباب التوبةِ مفتوحٌ ما لم تبلغ الروحُ الحلقوم أو تطلع الشمسُ من مغربها؛ فبادر قبل أن تقول: يا ليتني قدّمت لحياتي."}},{"n":4,"reflection":{"text":"«وعجبوا أن جاءهم منذر منهم وقال الكافرون هذا ساحر كذاب» — وتعجّب المشركون أن جاءهم رسولٌ منذِرٌ من جنسهم يعرفونه، ووصفوه بالسحرِ والكذب؛ ففي هذا بيانُ عنادهم ورميهم الحقَّ بالباطل؛ فاحذر أن تردّ الحقَّ بالتهمِ الباطلة، بل تأمّل الحقَّ بإنصاف، فردُّ الحقِّ بالسبِّ والتهمةِ من صفاتِ المعاندين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تأمّلُ الحقِّ بإنصاف، وتركُ ردِّه بالتهمِ الباطلة."},"action":{"text":"اعلم أنّ المشركين تعجّبوا أن يأتيهم رسولٌ منذِرٌ بشرٌ من جنسهم يعرفون نسبه وصدقه، فبادروا إلى ردِّ دعوته برميِه بالسحرِ والكذب «وعجبوا أن جاءهم منذر منهم وقال الكافرون هذا ساحر كذاب»؛ فهذا دأبُ المعاندين: ردُّ الحقِّ بالتهمِ والسبِّ لا بالحجّةِ والدليل؛ فاحذر أن تردّ الحقَّ إذا جاءك برميِ صاحبه بالتهمِ الباطلة؛ بل تأمّل الحقَّ بإنصافٍ وتجرّد، وانظر في الحجّةِ والدليل؛ فمن ردّ الحقَّ بالتهمةِ والشتمِ فقد أعرض عن الإنصاف؛ فاجعل ميزانك في قبولِ القولِ ودفعه: الحجّةَ والبرهانَ، لا الهوى والتشهير؛ فكم من حقٍّ رُدّ بتهمةٍ باطلة؛ فلا تكن ممّن يقابل الناصحَ بالاتّهام؛ بل اقبل النصحَ والحقَّ ممّن جاء به؛ فالإنصافُ عزيز، وأهله قليل؛ فكن من المنصفين الذين يزنون الأقوالَ بميزانِ الحقّ."}},{"n":5,"reflection":{"text":"«أجعل الآلهة إلها واحدا إن هذا لشيء عجاب» — أاختصر الآلهةَ الكثيرةَ في إلهٍ واحد؟ إنّ هذا لشيءٌ عجيبٌ مستنكَر (في زعمهم)؛ ففي هذا استعظامهم التوحيدَ الذي هو أعظمُ الحقّ؛ فتأمّل انقلابَ الموازين عند أهلِ الباطل: يستعظمون الحقَّ ويستنكرونه، فاحذر أن ينقلب ميزانك، واعلم أنّ التوحيدَ أعظمُ الحقِّ وأبينُه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ التوحيدِ وإدراكُ أنه أعظمُ الحقّ، لا العجب."},"action":{"text":"تأمّل كيف استعظم المشركون دعوةَ التوحيدِ واستنكروها، فقالوا متعجّبين: أاختصر الآلهةَ الكثيرةَ في إلهٍ واحد؟ إنّ هذا لشيءٌ عجيبٌ منكَر «أجعل الآلهة إلها واحدا إن هذا لشيء عجاب»؛ فانظر إلى انقلابِ الموازينِ عند أهلِ الباطل: يستعظمون أعظمَ الحقِّ وأبينَه — وهو توحيدُ الله — ويألفون أبطلَ الباطلِ وهو عبادةُ الأصنام؛ فاحذر أن ينقلب ميزانك فتستنكر الحقَّ وتألف الباطل؛ واعلم أنّ التوحيدَ أعظمُ الحقِّ وأوضحه، وأنّ الشركَ أعظمُ الباطلِ وأقبحه؛ فالعقلُ السليمُ والفطرةُ المستقيمةُ تشهد أنّ الإلهَ واحد؛ فكيف يُستعجَب من عبادةِ إلهٍ واحدٍ خالقٍ رازق، ولا يُستعجَب من عبادةِ آلهةٍ عاجزةٍ لا تنفع ولا تضرّ؟ فعظّم التوحيدَ في قلبك، وأنكِر الشركَ واستقبحه؛ فالتوحيدُ حقٌّ بيّن، والشركُ باطلٌ عجيب؛ فاجعل ميزانك ميزانَ الفطرةِ والعقلِ والوحي."}},{"n":6,"reflection":{"text":"«وانطلق الملأ منهم أن امشوا واصبروا على آلهتكم إن هذا لشيء يراد» — وانطلق أشرافُ المشركين يحرّض بعضهم بعضًا: امضوا واثبتوا على عبادةِ آلهتكم، إنّ هذا الأمرَ (دعوةَ التوحيد) يُرادُ بنا لغرض؛ ففي هذا تحريضُهم على الباطلِ وتواصيهم به؛ فاحذر التواصيَ على الباطلِ والثباتِ عليه، بل تواصَ مع إخوانك على الحقِّ والصبرِ عليه، فالتواصي بالحقِّ من صفاتِ الناجين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التواصي بالحقِّ والصبرِ عليه، لا على الباطل."},"action":{"text":"تأمّل كيف انطلق أشرافُ المشركين يحرّض بعضهم بعضًا على الثباتِ على الباطل: امضوا واصبروا على عبادةِ آلهتكم ولا تستجيبوا لدعوةِ التوحيد، إنّ هذا أمرٌ يُرادُ بنا «وانطلق الملأ منهم أن امشوا واصبروا على آلهتكم إن هذا لشيء يراد»؛ فتواصوا على الباطلِ والصبرِ عليه؛ فاحذر التواصيَ على الباطلِ والتحريضِ عليه والثباتِ فيه؛ بل تواصَ مع إخوانك على الحقِّ والصبرِ عليه؛ فالتواصي بالحقِّ والتواصي بالصبرِ من صفاتِ الناجين من الخسران؛ فكما يتواصى أهلُ الباطلِ على باطلهم، فتواصَ أنت وإخوانك على الحقِّ وطاعةِ الله والصبرِ عليها؛ فأعِن إخوانك على الخير، وثبّتهم على الحقّ؛ فالمؤمنُ للمؤمنِ كالبنيانِ يشدّ بعضه بعضًا؛ فاجعل صحبتك ومجالسك على التعاونِ على البرِّ والتقوى، والتواصي بالحقِّ والصبر؛ فالثباتُ على الحقِّ يقوى بالتواصي والتعاون."}},{"n":7,"reflection":{"text":"«ما سمعنا بهذا في الملة الآخرة إن هذا إلا اختلاق» — ما سمعنا بهذا التوحيدِ في دينِ آبائنا القريبِ أو النصرانية، ما هذا إلا كذبٌ مفترى؛ ففي هذا احتجاجهم بالتقليدِ وردُّ الحقِّ بعدمِ الإلفِ به؛ فاحذر ردَّ الحقِّ لمجرّدِ أنك لم تألفه أو خالف ما عليه الناس، بل زِن الحقَّ بدليله لا بألفةِ الناسِ له.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"وزنُ الحقِّ بدليله لا بألفةِ الناسِ له أو تقليدهم."},"action":{"text":"اعلم أنّ المشركين ردّوا دعوةَ التوحيدِ بحجّةٍ باطلة: أنهم لم يسمعوا به في دينِ آبائهم القريبِ ولا في الملةِ الأخيرة، وزعموا أنه كذبٌ مفترى «ما سمعنا بهذا في الملة الآخرة إن هذا إلا اختلاق»؛ فردّوا الحقَّ لمجرّدِ أنهم لم يألفوه ولم يسمعوا به من آبائهم؛ فاحذر ردَّ الحقِّ لمجرّدِ أنك لم تألفه، أو أنه خالف ما عليه أكثرُ الناسِ وآباؤك؛ فليست الغرابةُ وعدمُ الإلفِ دليلًا على البطلان؛ بل زِن الحقَّ بدليله وبرهانه، لا بألفةِ الناسِ له أو تقليدهم لآبائهم؛ فكم من حقٍّ ردّه الناسُ لأنهم لم يألفوه؛ فلا تجعل عادةَ الناسِ وتقليدَ الآباءِ ميزانًا للحقِّ والباطل؛ بل اجعل الميزانَ الوحيَ والدليلَ والعقلَ الصريح؛ فمن ردّ الحقَّ لأنه غريبٌ عليه فقد اتّبع هواه؛ فاقبل الحقَّ ولو كان غريبًا، ما دام الدليلُ يشهد له؛ فالحقُّ لا يُعرَف بألفةِ الناسِ ولا بكثرتهم، بل بدليله."}},{"n":8,"reflection":{"text":"«أأنزل عليه الذكر من بيننا بل هم في شك من ذكري بل لما يذوقوا عذاب» — أخُصَّ محمدٌ بالقرآنِ من بيننا؟ بل هم في شكٍّ من الوحي، بل لم يذوقوا عذابي بعدُ فيؤمنوا؛ ففي هذا حسدهم واعتراضهم على اختيارِ الله لرسوله؛ فاحذر الاعتراضَ على قسمةِ الله وفضلِه، فالله أعلمُ حيث يجعل رسالته وفضله، فسلّم لحكمةِ الله في اختياره واصطفائه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لحكمةِ الله في اختياره وفضلِه، وتركُ الاعتراض."},"action":{"text":"اعلم أنّ المشركين اعترضوا على اختيارِ الله لنبيّه محمدٍ ﷺ حسدًا: أخُصَّ بالقرآنِ والوحيِ من بيننا؟ فردّ الله عليهم بأنهم في شكٍّ من الوحيِ لم يتيقّنوه، وأنهم لم يذوقوا عذابه بعدُ فيؤمنوا مضطرّين «أأنزل عليه الذكر من بيننا بل هم في شك من ذكري بل لما يذوقوا عذاب»؛ فاعترضوا على قسمةِ الله وفضلِه واصطفائه؛ فاحذر الاعتراضَ على قسمةِ الله وفضلِه وتدبيرِه؛ فالله أعلمُ حيث يجعل رسالته وفضله ونعمه؛ يختصّ برحمتِه من يشاء بحكمته؛ فسلّم لحكمةِ الله في اختياره واصطفائه وقسمتِه؛ ولا تعترض على تفضيلِ الله بعضَ خلقه على بعض؛ فالحسدُ والاعتراضُ على فضلِ الله من صفاتِ الكافرين؛ فارضَ بقسمةِ الله، واسأله من فضله، ولا تحسد الناسَ على ما آتاهم الله؛ فمن اعترض على قسمةِ الله فقد اعترض على حكمته؛ فسلّم وارضَ، واطلب فضلَ الله بالسؤالِ لا بالحسد."}},{"n":9,"reflection":{"text":"«أم عندهم خزائن رحمة ربك العزيز الوهاب» — أعندهم خزائنُ رحمةِ ربّك العزيزِ الغالبِ الوهّابِ كثيرِ العطاء، حتى يعطوا النبوّةَ من شاؤوا؟ ففي هذا بيانُ أنّ الفضلَ بيدِ الله وحده؛ فاعلم أنّ خزائنَ الفضلِ والرحمةِ بيدِ الله، فاطلبها منه وحده، ولا تحسد من آتاه الله فضله، فالوهّابُ يعطي من يشاء بحكمته.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الفضلِ من الله وحده، فخزائنُ رحمتِه بيده."},"action":{"text":"تأمّل ردَّ الله على المشركين المعترضين على النبوّة: أعندهم خزائنُ رحمةِ ربّك العزيزِ الغالبِ الوهّابِ كثيرِ العطاء، حتى يتحكّموا فيمن ينزل عليه الوحيُ والرسالة؟ «أم عندهم خزائن رحمة ربك العزيز الوهاب»؛ فخزائنُ الرحمةِ والفضلِ بيدِ الله وحده، يؤتيها من يشاء بحكمته؛ فاعلم أنّ الفضلَ كلَّه — النبوّةَ والعلمَ والرزقَ والولدَ وكلَّ نعمة — بيدِ الله، خزائنه لا تنفد؛ فاطلب الفضلَ والرحمةَ من الله وحده، فهو الوهّابُ العزيز؛ ولا تحسد من آتاه الله من فضله؛ فالله يعطي من يشاء بحكمته وعلمه؛ فألحّ على الله في طلبِ فضله ورحمته؛ فخزائنه ملأى لا تغيضها النفقة؛ فمن سأل الله من فضله أعطاه، ومن حسد الناسَ على فضلِ الله حُرِم؛ فاجعل رغبتك إلى الله الوهّاب؛ فهو العزيزُ الذي لا يُغالَب، الوهّابُ الذي لا ينفد عطاؤه؛ فاطلب من خزائنِ رحمتِه، وارضَ بقسمته، ولا تعترض على فضله."}},{"n":10,"reflection":{"text":"«أم لهم ملك السماوات والأرض وما بينهما فليرتقوا في الأسباب» — ألهم مُلكُ السماواتِ والأرضِ حتى يتصرّفوا في أمرِ النبوّةِ والرسالة؟ فإن زعموا ذلك فليصعدوا في الطرقِ الموصلةِ إلى السماءِ ليدبّروا الأمر؛ ففي هذا تعجيزهم وبيانُ أنّ المُلكَ والتدبيرَ لله وحده؛ فاعلم أنّ المُلكَ والتدبيرَ كلَّه لله، فسلّم لتدبيرِه، ولا تنازعه في أمره، فالأمرُ كلُّه بيده.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لتدبيرِ الله، فالمُلكُ والأمرُ كلُّه بيده."},"action":{"text":"تأمّل تعجيزَ الله للمشركين المعترضين: ألهم مُلكُ السماواتِ والأرضِ وما بينهما، حتى يتحكّموا في أمرِ النبوّةِ والتدبير؟ فإن ادّعوا ذلك فليصعدوا في الأسبابِ والطرقِ الموصلةِ إلى السماءِ ليدبّروا الأمرَ ويمنعوا الوحيَ عمّن يشاؤون «أم لهم ملك السماوات والأرض وما بينهما فليرتقوا في الأسباب»؛ وهم عاجزون عن ذلك أشدَّ العجز؛ فالمُلكُ والتدبيرُ كلُّه لله وحده، لا يشاركه فيه أحد؛ فاعلم أنّ مُلكَ السماواتِ والأرضِ وتدبيرَ الأمرِ كلَّه بيدِ الله؛ فسلّم لتدبيرِ الله في خلقه، ولا تنازعه في أمره وحكمه؛ فمن أراد أن يدبّر مع الله أو يعترض على حكمه فقد جهل قدره وعجزه؛ فأنت وكلُّ الخلقِ عبيدٌ فقراءُ لا تملكون لأنفسكم نفعًا ولا ضرًّا؛ فكيف تنازعون مالكَ المُلكِ في تدبيره؟ فاخضع لله، وسلّم لأمره، وارضَ بحكمه؛ فالأمرُ كلُّه بيده، يدبّره بحكمته وعلمه؛ فما لك إلا التسليمُ والانقياد."}},{"n":11,"reflection":{"text":"«جند ما هنالك مهزوم من الأحزاب» — هؤلاء المشركون المتحزّبون على النبيِّ جندٌ حقيرٌ مهزومٌ لا محالة، كما هُزِمت الأحزابُ من قبلهم؛ ففي هذا بشارةٌ بهزيمةِ أعداءِ الحقِّ وتسليةٌ للنبيّ؛ فاعلم أنّ أعداءَ الحقِّ مهزومون ولو تحزّبوا وكثروا، فاثبت على الحقِّ ولا تخف كثرتهم، فالعاقبةُ للحقِّ وأهله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بهزيمةِ أعداءِ الحقِّ ولو تحزّبوا، والثباتُ عليه."},"action":{"text":"اعلم أنّ الله وصف المشركين المتحزّبين على النبيِّ ﷺ بأنهم جندٌ حقيرٌ مهزومٌ لا محالة، كما هُزِمت الأحزابُ المكذّبةُ من قبلهم «جند ما هنالك مهزوم من الأحزاب»؛ فهذه بشارةٌ بهزيمةِ أعداءِ الحقِّ وتسليةٌ للنبيِّ وأتباعه، وقد تحقّقت يومَ بدرٍ وغيره؛ فاعلم أنّ أعداءَ الحقِّ مهزومون مغلوبون ولو تحزّبوا وتكاثروا وأعدّوا؛ فالعاقبةُ للحقِّ وأهله؛ فاثبت على الحقِّ، ولا تخف كثرةَ المخالفين وتحزّبهم؛ فكم من فئةٍ قليلةٍ غلبت فئةً كثيرةً بإذنِ الله؛ فلا يهولنّك اجتماعُ أهلِ الباطلِ وكثرتهم؛ فإنّ نصرَ الله لأوليائه قريب، وهزيمةَ أعدائه محقّقة؛ فتوكّل على الله، واثبت على دينك، وابذل الأسباب؛ ثم ثق بوعدِ الله بنصرِ أوليائه وهزيمةِ أعدائه؛ فالباطلُ وإن انتفش وتحزّب فمصيره الزوالُ والهزيمة؛ فالعاقبةُ للمتّقين، والغلبةُ لجندِ الله."}}]},{"title":"تكذيبُ الأحزابِ السابقين ووعيدُهم، والأمرُ بالصبرِ وذكرِ داودَ الأوّاب","range":[12,20],"theme":"عدُّ الأممِ المكذّبةِ المهلَكة (قومِ نوحٍ وعادٍ وفرعونَ وثمودَ وقومِ لوطٍ وأصحابِ الأيكة) وأنّ تكذيبَ الرسلِ أوجب عقابهم، وأنّ المكذّبين ما ينتظرون إلا صيحةً واحدة، واستهزاؤهم باستعجالِ العذاب، والأمرُ للنبيِّ بالصبرِ وذكرِ داودَ ذي القوّةِ في العبادةِ الأوّابِ الذي سُخّرت معه الجبالُ والطيرُ تسبّح، وأوتي المُلكَ والحكمةَ وفصلَ الخطاب","verses":[{"n":12,"reflection":{"text":"«كذبت قبلهم قوم نوح وعاد وفرعون ذو الأوتاد» — كذّب قبل هؤلاء المشركين قومُ نوحٍ وعادٌ وفرعونُ صاحبُ الجنودِ والقوّةِ (ذو الأوتاد)؛ ففي هذا تسليةُ النبيِّ بأنّ التكذيبَ سنّةُ الأممِ الظالمة؛ فاعلم أنّ تكذيبَ الحقِّ قديم، فلا يحزنك تكذيبُ المكذّبين، واصبر كما صبر الرسلُ قبلك، فالتكذيبُ لا يضرّ الحقَّ ولا أهله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ على التكذيب، وإدراكُ أنه سنّةُ الأممِ الظالمة."},"action":{"text":"اعلم أنّ التكذيبَ للرسلِ سنّةٌ قديمةٌ في الأممِ الظالمة، فقد كذّب قبل مشركي قريشٍ قومُ نوحٍ وعادٌ قومُ هودٍ وفرعونُ صاحبُ القوّةِ والجنودِ والبطشِ (ذو الأوتاد) «كذبت قبلهم قوم نوح وعاد وفرعون ذو الأوتاد»؛ ففي هذا تسليةٌ للنبيِّ ﷺ وأتباعه، وبيانٌ أنّ ما يلقونه من التكذيبِ ليس بدعًا؛ فاعلم أنّ تكذيبَ الحقِّ وأهله قديمٌ متكرّر؛ فلا يحزنك تكذيبُ المكذّبين وإعراضُ المعرضين؛ واصبر على أذاهم كما صبر الرسلُ من قبلك؛ فالتكذيبُ لا يضرّ الحقَّ ولا أهله، وإنما يضرّ المكذّبين أنفسهم؛ فتأسَّ بالرسلِ في الصبرِ على التكذيبِ والأذى؛ فما لقيت من تكذيبٍ فقد لقي الرسلُ أعظمَ منه فصبروا؛ فاصبر واحتسب، وامضِ في الحقِّ غيرَ مبالٍ بتكذيبِ المكذّبين؛ فالعاقبةُ لك، والهلاكُ لهم، كما كانت عاقبةُ من كذّب الرسلَ من قبل."}},{"n":13,"reflection":{"text":"«وثمود وقوم لوط وأصحاب الأيكة أولئك الأحزاب» — وكذّب ثمودُ قومُ صالح، وقومُ لوط، وأصحابُ الأيكةِ قومُ شعيب؛ أولئك هم الأحزابُ المكذّبةُ التي أُهلِكت؛ ففي هذا عدُّ الأممِ المهلَكةِ للعبرة؛ فاعتبر بمصارعِ الأممِ المكذّبة، واحذر أن تسلك سبيلهم، فمن كذّب الحقَّ أهلكه الله، فاتّبع الحقَّ لتنجو من مصيرهم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بمصارعِ الأممِ المكذّبة، واتّباعُ الحقِّ للنجاة."},"action":{"text":"اعلم أنّ الله عدّ من الأحزابِ المكذّبةِ المهلَكة: ثمودَ قومَ صالح، وقومَ لوط، وأصحابَ الأيكةِ قومَ شعيب، مع من ذُكِر قبلهم؛ فقال: أولئك هم الأحزابُ الذين تحزّبوا على الحقِّ فأهلكهم الله «وثمود وقوم لوط وأصحاب الأيكة أولئك الأحزاب»؛ فاعتبر بمصارعِ هذه الأممِ المكذّبةِ التي أُهلِكت بتكذيبها؛ فكلٌّ منهم كذّب رسولَه فحقّ عليه العقاب؛ فاحذر أن تسلك سبيلهم في تكذيبِ الحقِّ والإعراضِ عنه؛ فمن كذّب الحقَّ وأصرّ عليه أهلكه الله كما أهلكهم؛ فاتّبع الحقَّ الذي جاءت به الرسلُ لتنجو من مصيرهم؛ فسِر في الأرضِ وانظر كيف كان عاقبةُ المكذّبين؛ فاجعل من مصارعهم عبرةً تحملك على الإيمانِ والاتّباع؛ فما هلكوا إلا بالتكذيبِ والعناد؛ فالنجاةُ في اتّباعِ الحقِّ والإيمانِ بالرسل، والهلاكُ في تكذيبهم والإعراضِ عنهم."}},{"n":14,"reflection":{"text":"«إن كل إلا كذب الرسل فحق عقاب» — ما كان كلُّ واحدٍ من تلك الأممِ إلا مكذّبًا للرسل، فوجب عليهم عقابي وحلّ بهم؛ ففي هذا أنّ تكذيبَ الرسلِ سببُ العقاب؛ فاحذر تكذيبَ رسلِ الله، فمن كذّبهم حقّ عليه العقاب، فآمن بالرسلِ جميعًا وصدّقهم، فتصديقُ الرسلِ سببُ النجاة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من تكذيبِ الرسل، فهو سببُ العقاب، وتصديقُهم نجاة."},"action":{"text":"اعلم أنّ تلك الأممَ المهلَكةَ ما كان كلُّ واحدٍ منها إلا مكذّبًا لرسلِ الله، فوجب عليهم عقابُ الله وحلّ بهم جزاءَ تكذيبهم «إن كل إلا كذب الرسل فحق عقاب»؛ فتكذيبُ الرسلِ هو السببُ الجامعُ لهلاكهم وعقابهم؛ فاحذر تكذيبَ رسلِ الله أو الإعراضَ عمّا جاؤوا به؛ فمن كذّب الرسلَ أو رسولًا منهم حقّ عليه العقاب؛ فآمن بالرسلِ جميعًا وصدّقهم فيما بلّغوا؛ واعمل بما جاؤوا به من الحقّ؛ فتصديقُ الرسلِ والعملُ بما جاؤوا به سببُ النجاةِ والفوز؛ فلا تكن ممّن يكذّب الحقَّ فيحقّ عليه العقاب؛ بل كن من المصدّقين المتّبعين؛ فالرسلُ جاؤوا بالهدى ودينِ الحق؛ فمن اتّبعهم نجا وسعد، ومن كذّبهم هلك وشقي؛ فاجعل الإيمانَ بالرسلِ وتصديقهم واتّباعهم منهجَ حياتك؛ فبذلك تأمن العقابَ وتنال الثواب."}},{"n":15,"reflection":{"text":"«وما ينظر هؤلاء إلا صيحة واحدة ما لها من فواق» — وما ينتظر هؤلاء المكذّبون إلا صيحةً واحدةً (نفخةَ الصور) لا رجوعَ لها ولا مهلة؛ ففي هذا قربُ الأجلِ وسرعةُ مجيءِ الساعة؛ فاستعدّ للقاءِ الله، فالساعةُ قريبةٌ تأتي بغتة، فلا تغترّ بالمهلة، بل بادر بالعملِ قبل أن تفجأك الصيحة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ للقاءِ الله، فالساعةُ قريبةٌ تأتي بغتة."},"action":{"text":"اعلم أنّ الله بيّن أنّ هؤلاء المكذّبين ما ينتظرون إلا صيحةً واحدةً — وهي نفخةُ الصورِ للبعثِ أو الهلاك — لا رجوعَ لها ولا مهلةَ ولا إفاقة «وما ينظر هؤلاء إلا صيحة واحدة ما لها من فواق»؛ فالساعةُ قريبةٌ تأتي بغتةً في صيحةٍ واحدة؛ فاستعدّ للقاءِ الله بالإيمانِ والعملِ الصالحِ قبل مجيئها؛ فلا تغترّ بالمهلةِ وطولِ الأمل؛ فالأجلُ قد يأتي بغتةً وأنت غافل؛ فبادر بالتوبةِ والعملِ قبل أن تفجأك الصيحةُ أو يحضرك الموت؛ فما بين أحدنا وبين الساعةِ إلا أن يموت؛ فمن مات فقد قامت قيامته؛ فاجعل نفسك مستعدًّا للرحيلِ في كلِّ لحظة؛ فالكيّسُ من دان نفسه وعمل لما بعد الموت؛ فلا تسوّف بالعمل؛ واعمل عملَ من يظنّ أنه لا يعيش إلا يومه؛ فالساعةُ آتيةٌ لا ريب فيها، قريبةٌ ولو استبعدها الغافلون؛ فاستعدّ لها بالإيمانِ والتقوى والعملِ الصالح."}},{"n":16,"reflection":{"text":"«وقالوا ربنا عجل لنا قطنا قبل يوم الحساب» — وقال المكذّبون استهزاءً: ربّنا عجّل لنا نصيبنا من العذابِ أو صحيفةَ أعمالنا قبل يومِ القيامة؛ ففي هذا استهزاؤهم بالوعيدِ واستعجالهم العذاب جهلًا؛ فاحذر الاستهزاءَ بوعيدِ الله واستعجالَه، فمن استهزأ بالعذابِ واستعجله سيندم حين يقع، فخذ الوعيدَ مأخذَ الجدّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الاستهزاءِ بالوعيدِ واستعجالِ العذاب."},"action":{"text":"تأمّل استهزاءَ المكذّبين بالوعيدِ واستعجالهم العذاب جهلًا وتكذيبًا: ربّنا عجّل لنا نصيبنا من العذابِ أو صحيفةَ أعمالنا قبل يومِ الحساب «وقالوا ربنا عجل لنا قطنا قبل يوم الحساب»؛ فطلبوا تعجيلَ العذابِ استهزاءً وتكذيبًا بوقوعه؛ فاحذر الاستهزاءَ بوعيدِ الله واستعجالَ عذابه؛ فمن استهزأ بالعذابِ واستعجله جاهلًا سيندم أشدَّ الندمِ حين يقع به؛ فلا تستهن بوعيدِ الله ولا تأمن مكره؛ فلا يأمن مكرَ الله إلا القومُ الخاسرون؛ فخذ وعيدَ الله مأخذَ الجدِّ والحذر؛ واستعدّ للقائه بالإيمانِ والعمل؛ فالعاقلُ من خاف عذابَ الله فاجتنب أسبابه، لا من استعجله واستهزأ به؛ فإذا سمعت وعيدَ الله فخف واحذر وبادر بالتوبة؛ فمن استهزأ بوعيدِ الله فقد جهل عظمةَ الله وشدّةَ عقابه؛ فاجعل خوفك من عذابِ الله حافزًا للطاعةِ والاستعداد، لا مادّةً للاستهزاءِ والاستعجال."}},{"n":17,"reflection":{"text":"«اصبر على ما يقولون واذكر عبدنا داوود ذا الأيد إنه أواب» — اصبر يا محمدُ على أذى المكذّبين وأقوالهم، وتذكّر عبدنا داودَ صاحبَ القوّةِ في العبادةِ والبطش، إنه رجّاعٌ إلى الله بالتوبةِ والطاعة؛ ففي هذا الأمرُ بالصبرِ والتأسّي بالأنبياء؛ فاصبر على الأذى، وتأسَّ بالصالحين في الصبرِ والأوبةِ إلى الله، فذكرُ سيرِ الصالحين يعين على الصبرِ والطاعة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ على الأذى، والتأسّي بالأنبياءِ في الأوبةِ إلى الله."},"action":{"text":"اعلم أنّ الله أمر نبيَّه ﷺ بالصبرِ على أذى المكذّبين وأقوالهم، وأمره أن يتذكّر عبدَه داودَ صاحبَ القوّةِ في العبادةِ والصبرِ والطاعة، الذي كان أوّابًا رجّاعًا إلى الله في كلِّ أموره «اصبر على ما يقولون واذكر عبدنا داوود ذا الأيد إنه أواب»؛ ففي هذا الأمرُ بالصبرِ على الأذى والتأسّي بالأنبياءِ والصالحين؛ فاصبر على أذى الناسِ وأقوالهم كما صبر الأنبياء؛ وتأسَّ بالصالحين في صبرهم وقوّتهم في الطاعةِ وأوبتهم إلى الله؛ فذكرُ سيرِ الصالحين وأخبارهم يعين على الصبرِ والاقتداءِ بهم؛ فاجعل داودَ وأمثاله قدوةً لك في القوّةِ على الطاعةِ والرجوعِ إلى الله؛ فالأوّابُ هو الرجّاعُ إلى الله بالتوبةِ والذكرِ والطاعةِ كلّما أذنب أو غفل؛ فكن أوّابًا رجّاعًا إلى الله؛ وتقوَّ على العبادةِ والطاعةِ كما تقوّى داود؛ فبالصبرِ والأوبةِ إلى الله تُنال معيّتُه ومحبّته؛ فاصبر على الأذى، وعُد إلى الله في كلِّ حين."}},{"n":18,"reflection":{"text":"«إنا سخرنا الجبال معه يسبحن بالعشي والإشراق» — إنا سخّرنا الجبالَ تسبّح مع داودَ في المساءِ والصباح؛ ففي هذا بيانُ فضلِ الله على داودَ وأنّ الجمادَ يسبّح لله؛ فاعلم أنّ الكونَ كلَّه يسبّح لله، فاقتدِ بالجبالِ والطيرِ في تسبيحِ الله، وأكثر من تسبيحه في طرفيِ النهار، فالتسبيحُ عبادةُ الكونِ كلِّه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإكثارُ من تسبيحِ الله، فالكونُ كلُّه يسبّح له."},"action":{"text":"اعلم أنّ الله أنعم على داودَ فسخّر معه الجبالَ تسبّح لله في العشيِّ والإشراقِ — أي في المساءِ والصباح — تأييدًا له وتفضيلًا «إنا سخرنا الجبال معه يسبحن بالعشي والإشراق»؛ فالجبالُ الجامدةُ تسبّح لله بأمره؛ فاعلم أنّ الكونَ كلَّه — جماده وحيّه — يسبّح لله ويحمده؛ وإن من شيءٍ إلا يسبّح بحمده ولكن لا تفقهون تسبيحهم؛ فاقتدِ بالجبالِ والطيرِ وسائرِ المخلوقاتِ في تسبيحِ الله؛ وأكثر من تسبيحِ الله وتحميده، لا سيّما في طرفيِ النهارِ صباحًا ومساءً؛ فسبّح بحمدِ ربك قبل طلوعِ الشمسِ وقبل الغروب؛ فالتسبيحُ عبادةُ الكونِ كلِّه، وهو ثقيلٌ في الميزان، حبيبٌ إلى الرحمن؛ فاعمر لسانك وقلبك بتسبيحِ الله في كلِّ حين؛ فإذا سبّحت فأنت في صفِّ الجبالِ والطيرِ والملائكةِ والكونِ كلِّه في تعظيمِ الله؛ فاجعل التسبيحَ وردك الدائمَ صباحًا ومساء."}},{"n":19,"reflection":{"text":"«والطير محشورة كل له أواب» — وسخّرنا الطيرَ مجموعةً معه تسبّح، كلٌّ من الجبالِ والطيرِ مطيعٌ رجّاعٌ إلى الله بالتسبيح؛ ففي هذا تمامُ نعمةِ الله على داودَ وانقيادُ الخلقِ لله؛ فتأمّل انقيادَ الطيرِ والجبالِ لله بالتسبيح، فكن أنت أولى بالانقيادِ والأوبةِ إلى الله، فالمخلوقاتُ كلُّها أوّابةٌ إلى ربها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الانقيادُ لله والأوبةُ إليه، اقتداءً بالخلقِ المسبّح."},"action":{"text":"اعلم أنّ الله سخّر مع داودَ الطيرَ مجموعةً محشورةً تسبّح معه، وكلٌّ من الجبالِ والطيرِ مطيعٌ منقادٌ أوّابٌ رجّاعٌ إلى الله بالتسبيحِ والطاعة «والطير محشورة كل له أواب»؛ فتأمّل كيف انقادت الجبالُ والطيرُ لله تسبّحه وترجع إليه؛ فإذا كانت الجبالُ الصمُّ والطيرُ العُجمُ تسبّح لله وترجع إليه، فأنت — أيها الإنسانُ المكرّمُ العاقل — أولى بالانقيادِ لله والأوبةِ إليه والتسبيحِ له؛ فكن أوّابًا رجّاعًا إلى الله في كلِّ أمرك؛ فالمخلوقاتُ كلُّها منقادةٌ لله، مسبّحةٌ بحمده، راجعةٌ إليه؛ فلا تكن أقلَّ انقيادًا من الجبالِ والطير؛ بل سبّح الله، وأطعه، وارجع إليه في كلِّ حين؛ فاجعل قلبك ولسانك وجوارحك في طاعةِ الله وتسبيحه؛ فالأوبةُ إلى الله والانقيادُ له غايةُ العبودية؛ فاقتدِ بالكونِ المسبّحِ المنقادِ، وكن من الأوّابين إلى ربك."}},{"n":20,"reflection":{"text":"«وشددنا ملكه وآتيناه الحكمة وفصل الخطاب» — وقوّينا مُلكَ داودَ بالهيبةِ والنصرِ والجندِ، وأعطيناه الحكمةَ والنبوّةَ والفصلَ في القضاءِ والكلام؛ ففي هذا تمامُ فضلِ الله عليه؛ فاعلم أنّ التمكينَ والحكمةَ من فضلِ الله، فاسأله الحكمةَ والفصلَ في أمورك، واشكر ما آتاك من نعمة، فالحكمةُ خيرٌ كثير.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الحكمةِ من الله، وشكرُ نعمةِ التمكين."},"action":{"text":"اعلم أنّ الله أتمّ فضله على داودَ فقوّى مُلكه بالهيبةِ والنصرِ وكثرةِ الجند، وأعطاه الحكمةَ والنبوّةَ، وفصلَ الخطابِ — وهو الفصلُ في القضاءِ بين الناسِ والبيانُ الواضحُ في الكلام «وشددنا ملكه وآتيناه الحكمة وفصل الخطاب»؛ فالتمكينُ والحكمةُ والبيانُ من فضلِ الله ومنّته؛ فاعلم أنّ ما يؤتاه العبدُ من مُلكٍ وتمكينٍ وحكمةٍ وعلمٍ فمن فضلِ الله؛ فاسأل الله الحكمةَ والفصلَ والسدادَ في أمورك وأقوالك وأحكامك؛ فالحكمةُ خيرٌ كثير، ومن يؤت الحكمةَ فقد أوتي خيرًا كثيرًا؛ واشكر الله على ما آتاك من نعمةِ التمكينِ والعلمِ والبيان؛ فمن شكر النعمةَ زادها الله؛ واستعمل ما آتاك الله من قوّةٍ وحكمةٍ في طاعتِه ونفعِ عباده والحكمِ بالعدل؛ فالنعمُ أماناتٌ تُشكَر بحسنِ استعمالها؛ فاطلب الحكمةَ، واشكر النعمة، واستعملها في مرضاةِ الله."}}]},{"title":"خصومةُ الملكينِ، وحكمُ داودَ وتوبتُه، واستخلافُه، وحكمةُ الخلقِ وتدبّرُ القرآن","range":[21,29],"theme":"قصةُ الخصمينِ اللذينِ تسوّرا محرابَ داودَ يطلبان الحكمَ بالعدل، وشكوى صاحبِ النعجةِ الواحدةِ من بغيِ صاحبِ التسعِ والتسعين، وحكمُ داودَ ثم علمُه أنه فُتِن فاستغفر وخرّ راكعًا وأناب فغُفِر له وله زلفى، ووصيّتُه بالحكمِ بالحقِّ وتركِ الهوى وتذكّرِ يومِ الحساب، وأنّ خلقَ السماءِ والأرضِ بحقٍّ لا باطلًا، وأنّ الله لا يسوّي بين المؤمنِ والمفسدِ، وأنّ القرآنَ أُنزِل ليُتدبَّر","verses":[{"n":21,"reflection":{"text":"«وهل أتاك نبأ الخصم إذ تسوروا المحراب» — وهل بلغك خبرُ الخصمِ حين تسلّقوا على داودَ محرابه وموضعَ عبادته؟ ففي هذا تشويقٌ لقصّةٍ فيها عبرة؛ فتهيّأ للاعتبارِ بقصصِ القرآن، فكلُّ قصّةٍ فيها عبرةٌ ودرس، فاقرأ قصصَ القرآنِ بقلبٍ حاضرٍ متدبّرٍ لتأخذ عبرتها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التهيّؤُ للاعتبارِ بقصصِ القرآنِ وأخذِ عبرتها."},"action":{"text":"اعلم أنّ الله شوّق نبيَّه لسماعِ قصّةِ الخصمِ الذين تسلّقوا على داودَ سورَ محرابه وموضعِ عبادته ليحتكموا إليه «وهل أتاك نبأ الخصم إذ تسوروا المحراب»؛ فهذا الاستفهامُ للتشويقِ والتنبيهِ على أنّ فيما يأتي عبرةً ودرسًا؛ فتهيّأ للاعتبارِ بقصصِ القرآنِ العظيم؛ فما قصّ الله علينا القصصَ إلا لنعتبر ونتّعظ ونثبّت به قلوبنا؛ فكلُّ قصّةٍ في القرآنِ فيها عبرةٌ ودرسٌ وحكمة؛ فاقرأ قصصَ القرآنِ بقلبٍ حاضرٍ متدبّرٍ متأمّل، لا بقلبٍ غافلٍ لاهٍ؛ واستخلص من كلِّ قصّةٍ عبرتها ودرسها وما تدلّ عليه من أسماءِ الله وصفاتِه وسننِه في خلقه؛ فقصّةُ داودَ فيها درسٌ في العدلِ في الحكم، والحذرِ من الاستعجالِ فيه، وسرعةِ الأوبةِ إلى الله عند الزلل؛ فاجعل قصصَ القرآنِ زادًا لإيمانك وعبرةً لقلبك؛ فلقد كان في قصصهم عبرةٌ لأولي الألباب."}},{"n":22,"reflection":{"text":"«إذ دخلوا على داوود ففزع منهم قالوا لا تخف خصمان بغى بعضنا على بعض فاحكم بيننا بالحق ولا تشطط واهدنا إلى سواء الصراط» — حين دخلوا عليه فجأةً ففزع، فطمأنوه: لا تخف، نحن خصمان بغى بعضنا على بعض، فاحكم بيننا بالعدل ولا تجُر، وأرشدنا إلى وسطِ الطريق؛ ففي هذا طلبُ الحكمِ بالحقِّ والعدل؛ فاطلب الحكمَ بالعدلِ في خصوماتك، واحكم بالحقِّ إن حكّمت، ولا تجُر، فالعدلُ في الحكمِ من أعظمِ القرب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الحكمِ بالعدل، والحكمُ بالحقِّ دون جورٍ ولا شطط."},"action":{"text":"تأمّل قصّةَ الخصمينِ اللذين دخلا على داودَ فجأةً في محرابه ففزع منهم، فطمأنوه: لا تخف، إنما نحن خصمان بغى بعضنا على بعض، فاحكم بيننا بالحقِّ والعدل، ولا تجُر ولا تَمِل، وأرشدنا إلى وسطِ الطريقِ وسوائه «إذ دخلوا على داوود ففزع منهم قالوا لا تخف خصمان بغى بعضنا على بعض فاحكم بيننا بالحق ولا تشطط واهدنا إلى سواء الصراط»؛ فطلبوا منه الحكمَ بالعدلِ والإرشادَ إلى الحق؛ فاطلب أنت الحكمَ بالعدلِ في خصوماتك، وارضَ بحكمِ الحقِّ عليك ولك؛ وإن حكّمك الناسُ فاحكم بينهم بالحقِّ والعدل، ولا تجُر ولا تمِل مع أحدٍ لهوًى أو قرابةٍ أو رشوة؛ فالعدلُ في الحكمِ من أعظمِ القرباتِ إلى الله؛ فالمقسطون على منابرَ من نورٍ عند الله؛ فاحرص على العدلِ في كلِّ حكمٍ تحكمه، ولو على نفسك وأقربِ الناسِ إليك؛ فلا تحملنّك عداوةُ قومٍ على ألا تعدلوا، اعدلوا هو أقربُ للتقوى؛ فالعدلُ ميزانُ الله في الأرض؛ فاجعله شعارك في أحكامك ومعاملاتك."}},{"n":23,"reflection":{"text":"«إن هذا أخي له تسع وتسعون نعجة ولي نعجة واحدة فقال أكفلنيها وعزني في الخطاب» — قال أحدهما: إنّ هذا أخي له تسعٌ وتسعون نعجة ولي واحدة، فقال: ضمّها إليّ، وغلبني في الحجّةِ والكلام؛ ففي هذا صورةٌ للبغيِ والطمعِ في حقِّ الغير؛ فاحذر الطمعَ في حقوقِ الناسِ والبغيَ عليهم، واقنع بما آتاك الله، فالطمعُ في حقِّ الغيرِ ظلمٌ وبغي، والقناعةُ كنزٌ لا يفنى.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الطمعِ في حقوقِ الناسِ والبغيِ عليهم، والقناعة."},"action":{"text":"تأمّل شكوى أحدِ الخصمينِ لداود: إنّ هذا أخي له تسعٌ وتسعون نعجة ولي نعجةٌ واحدة، فقال لي: ضمّها إليّ واتركها لي، وغلبني وقهرني في الحجّةِ والخطاب «إن هذا أخي له تسع وتسعون نعجة ولي نعجة واحدة فقال أكفلنيها وعزني في الخطاب»؛ فهذه صورةٌ للبغيِ والطمعِ في حقِّ الغير: صاحبُ التسعِ والتسعين يطمع في نعجةِ أخيه الواحدة؛ فاحذر الطمعَ في حقوقِ الناسِ والبغيَ عليهم مهما كثر ما عندك؛ فمن كان عنده الكثيرُ ثم طمع في القليلِ الذي عند غيره فهو الباغي الظالم؛ فاقنع بما آتاك الله، ولا تمدّنّ عينيك إلى ما متّع الله به غيرك؛ فالقناعةُ كنزٌ لا يفنى، وغنًى لا ينفد؛ فالغنى غنى النفس؛ فمن قنع بما رزقه الله استغنى وسعد، ومن طمع في حقوقِ الناسِ شقي وأثم؛ فطهّر قلبك من الطمعِ والبغي؛ واحفظ حقوقَ الناسِ كما تحبّ أن تُحفَظ حقوقك؛ فالبغيُ مرتعُه وخيم، وعاقبتُه سيّئة."}},{"n":24,"reflection":{"text":"«قال لقد ظلمك بسؤال نعجتك إلى نعاجه وإن كثيرا من الخلطاء ليبغي بعضهم على بعض إلا الذين آمنوا وعملوا الصالحات وقليل ما هم وظن داوود أنما فتناه فاستغفر ربه وخر راكعا وأناب» — حكم داودُ بأنّ الطالبَ ظلمه، ونبّه أنّ كثيرًا من الشركاءِ يبغي بعضهم على بعض إلا المؤمنين الصالحين وقليلٌ هم، ثم علم داودُ أنّا اختبرناه (بحكمِه قبل سماعِ الخصمِ الآخر) فاستغفر وسجد وتاب؛ ففي هذا سرعةُ أوبةِ داودَ عند الزلل؛ فبادر بالاستغفارِ والتوبةِ عند الزلل، واسجد لله منيبًا، فالأوّابُ من رجع إلى الله فورَ زلّته.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ بالاستغفارِ والتوبةِ والإنابةِ عند الزلل."},"action":{"text":"تأمّل حكمَ داودَ ثم أوبتَه: قال للطالبِ لقد ظلمك أخوك بطلبِ نعجتك ليضمّها إلى نعاجه، ونبّه أنّ كثيرًا من الشركاءِ والخلطاءِ يبغي بعضهم على بعض، إلا المؤمنين الصالحين وقليلٌ ما هم؛ ثم علم داودُ أنّ الله اختبره بهذه الحادثة — إذ حكم لأحدهما قبل أن يسمع من الآخر — فبادر بالاستغفارِ وخرّ ساجدًا وأناب إلى الله «قال لقد ظلمك... وظن داوود أنما فتناه فاستغفر ربه وخر راكعا وأناب»؛ ففي هذا سرعةُ أوبةِ داودَ ورجوعِه إلى الله عند الزلل؛ فتعلّم من داودَ المبادرةَ بالاستغفارِ والتوبةِ والإنابةِ عند الزللِ والخطأ؛ فلا تصرّ على زلّة، ولا تسوّف بالتوبة؛ بل بادر فورَ وقوعِ الخطأ بالاستغفارِ والرجوعِ إلى الله؛ واسجد لله منيبًا خاشعًا؛ فالسجودُ من أعظمِ أسبابِ القربِ من الله؛ (وهذا موضعُ سجدةِ تلاوة)؛ فالأوّابُ هو من يرجع إلى الله فورَ زلّته بالتوبةِ والإنابة؛ فكن أوّابًا لا مصرًّا؛ فمن بادر بالتوبةِ غفر الله له كما غفر لداود؛ واحذر أيضًا الحكمَ قبل سماعِ الطرفين؛ فالعدلُ أن تسمع من الخصمين قبل أن تحكم."}},{"n":25,"reflection":{"text":"«فغفرنا له ذلك وإن له عندنا لزلفى وحسن مآب» — فغفرنا لداودَ زلّته، وإنّ له عندنا لقربةً ومنزلةً رفيعةً وحسنَ مرجع؛ ففي هذا ثمرةُ التوبةِ: المغفرةُ والقربةُ ورفعةُ المنزلة؛ فاعلم أنّ التوبةَ الصادقةَ تجلب المغفرةَ والقربَ من الله، فتب إلى الله صادقًا، فالتائبُ يرفعه الله ويقرّبه، فلا تيأس من رحمةِ الله بعد الزلل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرجاءُ في ثمرةِ التوبة: المغفرةُ والقربُ ورفعةُ المنزلة."},"action":{"text":"اعلم أنّ الله غفر لداودَ زلّته لمّا تاب وأناب، بل رفع منزلته فجعل له عنده قربةً ومكانةً رفيعةً وحسنَ مرجعٍ ومآب «فغفرنا له ذلك وإن له عندنا لزلفى وحسن مآب»؛ فهذه ثمرةُ التوبةِ الصادقة: المغفرةُ للذنب، والقربُ من الله، ورفعةُ المنزلة، وحسنُ العاقبة؛ فاعلم أنّ التوبةَ الصادقةَ لا تمحو الذنبَ فحسب، بل ترفع صاحبها وتقرّبه من الله؛ فالتائبُ من الذنبِ كمن لا ذنبَ له، وقد يرفعه الله بتوبتِه فوقَ منزلتِه قبلها؛ فتب إلى الله توبةً صادقةً نصوحًا؛ ولا تيأس من رحمةِ الله بعد الزللِ والذنب؛ فإنّ الله يحبّ التوّابين ويقرّبهم؛ فمن تاب تاب الله عليه، ورفع منزلته، وأحسن مرجعه؛ فلا تجعل الذنبَ يقنّطك من رحمةِ الله؛ بل اجعله بابًا للتوبةِ والأوبةِ والقرب؛ فالله يفرح بتوبةِ عبده؛ فبادر بالتوبة، وأحسن الظنَّ بالله، وارجُ مغفرته وقربه وحسنَ مآبه؛ فرحمةُ الله وسعت كلَّ شيء، وهي قريبةٌ من التائبين المنيبين."}},{"n":26,"reflection":{"text":"«يا داوود إنا جعلناك خليفة في الأرض فاحكم بين الناس بالحق ولا تتبع الهوى فيضلك عن سبيل الله إن الذين يضلون عن سبيل الله لهم عذاب شديد بما نسوا يوم الحساب» — يا داودُ جعلناك خليفةً حاكمًا في الأرض، فاحكم بين الناسِ بالعدل، ولا تتّبع الهوى فيصرفك عن طريقِ الله؛ إنّ الضالّين عن سبيلِ الله لهم عذابٌ شديدٌ بنسيانهم يومَ الحساب؛ ففي هذا وصيّةُ الحاكمِ بالعدلِ وتركِ الهوى؛ فاحكم بالحقِّ في كلِّ ما وُلّيت، واحذر اتّباعَ الهوى، فإنه يُضلّ عن سبيلِ الله، وتذكّر يومَ الحسابِ ليستقيم عملك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحكمُ بالحقِّ وتركُ الهوى، وتذكّرُ يومِ الحسابِ في العمل."},"action":{"text":"تأمّل وصيّةَ الله لداودَ الخليفةِ الحاكم: يا داودُ إنا جعلناك خليفةً في الأرضِ تحكم بين الناس، فاحكم بينهم بالحقِّ والعدل، ولا تتّبع الهوى في حكمك فيصرفك عن سبيلِ الله؛ إنّ الذين يضلّون عن سبيلِ الله لهم عذابٌ شديدٌ بسببِ نسيانهم يومَ الحساب «يا داوود إنا جعلناك خليفة في الأرض فاحكم بين الناس بالحق ولا تتبع الهوى فيضلك عن سبيل الله...»؛ ففي هذا وصيّةٌ جامعةٌ لكلِّ من وُلّي أمرًا: الحكمُ بالحقِّ، وتركُ اتّباعِ الهوى؛ فاحكم بالحقِّ والعدلِ في كلِّ ما وُلّيت من أمرِ نفسك وأهلك ومن تحت يدك؛ واحذر اتّباعَ الهوى في أحكامك وأقوالك وأفعالك؛ فإنّ الهوى يُضلّ عن سبيلِ الله؛ فما ذُكِر الهوى في القرآنِ إلا ذُمّ؛ فمن حكّم هواه ضلّ، ومن حكّم الحقَّ اهتدى؛ وتذكّر يومَ الحسابِ دائمًا؛ فتذكّره يقوّم العملَ ويردع عن الهوى والظلم؛ فمن نسي يومَ الحسابِ ضلّ وظلم، ومن استحضره استقام وعدل؛ فاجعل الحقَّ إمامك، والحسابَ نصبَ عينيك؛ فبذلك تستقيم وتنجو من العذابِ الشديد."}},{"n":27,"reflection":{"text":"«وما خلقنا السماء والأرض وما بينهما باطلا ذلك ظن الذين كفروا فويل للذين كفروا من النار» — وما خلقنا السماءَ والأرضَ وما بينهما عبثًا بلا حكمةٍ ولا بعثٍ ولا جزاء، ذلك ظنُّ الكافرين، فويلٌ لهم من النار؛ ففي هذا تقريرُ حكمةِ الخلقِ والبعثِ والجزاء؛ فاعلم أنّ خلقك لحكمةٍ وغاية، لا عبثًا، فاستعدّ للقاءِ الله والجزاء، ولا تظنّ أنّ الحياةَ عبثٌ بلا حساب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ حكمةِ الخلقِ والبعث، والاستعدادُ للجزاء."},"action":{"text":"اعلم أنّ الله ما خلق السماءَ والأرضَ وما بينهما عبثًا وباطلًا بلا حكمةٍ ولا غايةٍ ولا بعثٍ ولا جزاء؛ فمن ظنّ ذلك فهو ظنُّ الكافرين، فويلٌ لهم من النارِ التي أعدّها لهم «وما خلقنا السماء والأرض وما بينهما باطلا ذلك ظن الذين كفروا فويل للذين كفروا من النار»؛ فالكونُ مخلوقٌ بحكمةٍ بالغة، والإنسانُ مخلوقٌ لغايةٍ عظيمة: عبادةِ الله ثم البعثِ والجزاء؛ فاعلم أنّ خلقك لم يكن عبثًا، وأنك لن تُترَك سدًى بلا أمرٍ ولا نهيٍ ولا حسابٍ ولا جزاء؛ أفحسبتم أنما خلقناكم عبثًا وأنكم إلينا لا ترجعون؟ فاستعدّ للقاءِ الله والجزاءِ على عملك؛ ولا تظنّ أنّ الحياةَ عبثٌ ولهوٌ بلا حسابٍ ولا مآل؛ فمن آمن بحكمةِ الخلقِ والبعثِ استقام وعمل، ومن ظنّ العبثَ لها وأنكر البعثَ ضلّ وفسق؛ فتأمّل في حكمةِ خلقِ الله لتزداد إيمانًا؛ واعمل لغايةِ وجودك: عبادةِ الله والاستعدادِ للقائه؛ فالخلقُ بحقٍّ لا بباطل، والحياةُ لغايةٍ لا لعبث؛ فاعمل لما خُلِقت له."}},{"n":28,"reflection":{"text":"«أم نجعل الذين آمنوا وعملوا الصالحات كالمفسدين في الأرض أم نجعل المتقين كالفجار» — أنسوّي بين المؤمنين العاملين الصالحاتِ والمفسدين في الأرض؟ أم نسوّي بين المتّقين والفجّار؟ ففي هذا تقريرُ عدلِ الله وأنه لا يسوّي بين المؤمنِ والكافر؛ فاعلم أنّ الله لا يسوّي بين المحسنِ والمسيء، فاعمل صالحًا لتكون من المتّقين المكرمين، فالجزاءُ يفرّق بين الفريقين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بعدلِ الله، والعملُ الصالحُ لتمييزِ المتّقين."},"action":{"text":"تأمّل تقريرَ الله لعدلِه وحكمته: أيليق بعدلِ الله وحكمته أن يسوّي بين الذين آمنوا وعملوا الصالحاتِ والمفسدين في الأرض؟ أم يسوّي بين المتّقين والفجّار؟ «أم نجعل الذين آمنوا وعملوا الصالحات كالمفسدين في الأرض أم نجعل المتقين كالفجار»؛ فحاشا لله أن يسوّي بينهم؛ فهذا مقتضى حكمتِه وعدله؛ فلا بدّ من بعثٍ وجزاءٍ يُميّز فيه المحسنُ من المسيء؛ فاعلم أنّ الله لا يسوّي بين المؤمنِ والكافر، ولا بين المتّقي والفاجر، ولا بين المصلحِ والمفسد؛ فلكلٍّ جزاؤه اللائقُ به؛ فالمؤمنون في نعيم، والفجّار في جحيم؛ فاعمل صالحًا واتّق الله لتكون من المؤمنين المتّقين المكرمين؛ ولا تكن من المفسدين الفجّار المعذّبين؛ فالجزاءُ يفرّق بين الفريقين تفريقًا عظيمًا؛ فاختر لنفسك أيَّ الفريقين تكون؛ فالعملُ الصالحُ والتقوى سبيلُ الفوز، والفسادُ والفجورُ سبيلُ الخسران؛ فبادر بالإيمانِ والعملِ الصالحِ والتقوى، لتكون من أهلِ النعيمِ لا من أهلِ الجحيم؛ فعدلُ الله يقتضي التمييزَ بين المتّقي والفاجر."}},{"n":29,"reflection":{"text":"«كتاب أنزلناه إليك مبارك ليدبروا آياته وليتذكر أولو الألباب» — هذا القرآنُ كتابٌ مباركٌ كثيرُ الخيرِ أنزلناه إليك ليتدبّر الناسُ آياته ويتذكّر أصحابُ العقولِ السليمة؛ ففي هذا بيانُ الغايةِ من إنزالِ القرآن: التدبّرُ والتذكّر؛ فاجعل غايتك من القرآنِ التدبّرَ والتذكّرَ والعمل، لا مجرّدَ التلاوة، فالقرآنُ أُنزِل ليُتدبَّر ويُعمَل به، فتدبّر آياته بقلبك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تدبّرُ القرآنِ والتذكّرُ به، فتلك غايةُ إنزاله."},"action":{"text":"اعلم أنّ الله بيّن الغايةَ من إنزالِ القرآن: أنه كتابٌ مباركٌ كثيرُ الخيرِ والبركة، أنزله ليتدبّر الناسُ آياته ويفهموا معانيها، وليتذكّر بها أصحابُ العقولِ السليمة «كتاب أنزلناه إليك مبارك ليدبروا آياته وليتذكر أولو الألباب»؛ فالغايةُ من القرآنِ التدبّرُ والتذكّرُ والعمل، لا مجرّدُ التلاوةِ بلا فهم؛ فاجعل غايتك من قراءةِ القرآنِ التدبّرَ لآياته، والتذكّرَ بمواعظه، والعملَ بأحكامه؛ فأفلا يتدبّرون القرآنَ أم على قلوبٍ أقفالها؟ فلا تهذّ القرآنَ هذًّا بلا تدبّر؛ بل اقرأه بترتيلٍ وتأمّل، وقف عند آياته، وتفكّر في معانيها؛ فالتدبّرُ يفتح للقلبِ كنوزَ القرآنِ وأنواره؛ فمن تدبّر القرآنَ انتفع به واهتدى، ومن قرأه بلا تدبّرٍ فاته خيرٌ كثير؛ فاجعل لك وقفاتٍ تدبّريّةً مع القرآن؛ وتذكّر بما فيه من الوعدِ والوعيدِ والأمثالِ والقصص؛ فالقرآنُ مأدبةُ الله، فتعلّموا من مأدبته؛ فتدبّره بقلبٍ حاضرٍ، واعمل بمقتضاه؛ فبالتدبّرِ والعملِ تُنال بركةُ القرآن."}}]},{"title":"سليمانُ: مُلكُه وأوبتُه وتسخيرُ الريحِ والشياطين، وأيوبُ: بلاؤه وصبرُه وفرجُه","range":[30,44],"theme":"هبةُ سليمانَ لداودَ ومدحُه بالأوبة، وقصةُ الخيلِ التي شغلته فآثر ذكرَ ربه، وفتنتُه وإنابتُه ودعاؤه بمُلكٍ لا ينبغي لأحدٍ بعده، وتسخيرُ الريحِ والشياطينِ البنّائين والغوّاصين له وتفويضُه في العطاء، وأنّ له عند الله زلفى؛ ثم أيوبُ ونداؤه ربه من مسِّ الضرّ، وأمرُه بركضِ الأرضِ فنبعت عينُ الشفاء، وتعويضُه أهله ومثلهم، وأخذُه الضغثَ برًّا بيمينه، وثناءُ الله عليه بالصبرِ والأوبة","verses":[{"n":30,"reflection":{"text":"«ووهبنا لداوود سليمان نعم العبد إنه أواب» — ووهبنا لداودَ ابنه سليمانَ نبيًّا، نِعم العبدُ سليمان، إنه أوّابٌ رجّاعٌ إلى الله؛ ففي هذا نعمةُ الذريةِ الصالحةِ ومدحُ الأوّاب؛ فاسأل الله الذريةَ الصالحة، وكن أوّابًا رجّاعًا إلى الله، فمدحُ الله لسليمانَ بالأوبةِ يبيّن أنّ خيرَ العبادِ أوّابهم إلى الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الذريةِ الصالحة، وكونُ العبدِ أوّابًا إلى الله."},"action":{"text":"اعلم أنّ الله وهب لداودَ ابنه سليمانَ نبيًّا كريمًا، وأثنى عليه فقال: نِعم العبدُ سليمان، إنه أوّابٌ رجّاعٌ إلى الله بالتوبةِ والذكرِ والطاعة «ووهبنا لداوود سليمان نعم العبد إنه أواب»؛ ففي هذا نعمةُ الذريةِ الصالحةِ التي تخلف أباها في الخير، ومدحُ العبدِ الأوّاب؛ فاسأل الله الذريةَ الصالحةَ التي تقرّ بها عينك وتنفعك بعد موتك؛ فالولدُ الصالحُ من أعظمِ النعم؛ وكن أنت أوّابًا رجّاعًا إلى الله في كلِّ أمرك؛ فقد أثنى الله على داودَ وسليمانَ بالأوبة؛ فخيرُ العبادِ أوّابهم إلى الله؛ فالأوّابُ هو الرجّاعُ إلى الله بالتوبةِ كلّما أذنب، وبالذكرِ كلّما غفل، وبالطاعةِ كلّما فتر؛ فاجعل الأوبةَ إلى الله دأبك؛ كلّما زللت فتب، وكلّما غفلت فاذكر، وكلّما فترت فانشط؛ فبالأوبةِ المستمرّةِ إلى الله تُنال محبّته والثناءُ منه؛ فاطلب الذريةَ الصالحة، وكن عبدًا أوّابًا؛ فذلك سبيلُ الخيرِ في الدنيا والآخرة."}},{"n":31,"reflection":{"text":"«إذ عرض عليه بالعشي الصافنات الجياد» — حين عُرِض على سليمانَ في آخرِ النهارِ الخيلُ الأصيلةُ السريعةُ الواقفةُ على ثلاثٍ طرفَ الرابعة؛ ففي هذا ذكرُ نعمةِ الله على سليمانَ بالخيلِ التي أعدّها للجهاد؛ فاعلم أنّ اقتناءَ ما يُعين على طاعةِ الله وجهادِ عدوّه قربة، فاتّخذ من أسبابِ القوّةِ ما يُعينك على طاعةِ الله ونصرةِ دينه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اتّخاذُ أسبابِ القوّةِ لما يُعين على طاعةِ الله وجهادِ عدوّه."},"action":{"text":"اعلم أنّ الله ذكر من نعمِه على سليمانَ أن عُرِض عليه في آخرِ النهارِ الخيلُ الصافناتُ الجيادُ — وهي الخيلُ الأصيلةُ الكريمةُ السريعةُ التي تقف على ثلاثِ قوائمَ وتُقلّ الرابعة — التي أعدّها للجهادِ في سبيلِ الله «إذ عرض عليه بالعشي الصافنات الجياد»؛ فكانت الخيلُ عنده عُدّةً للجهادِ وطاعةِ الله؛ فاعلم أنّ اقتناءَ ما يُعين على طاعةِ الله وجهادِ عدوّه وإقامةِ دينه قربةٌ وطاعة؛ فاتّخذ من أسبابِ القوّةِ والعُدّةِ ما يُعينك على طاعةِ الله ونصرةِ دينه؛ وأعدّوا لهم ما استطعتم من قوّةٍ ومن رباطِ الخيل؛ فالقوّةُ المرصودةُ لطاعةِ الله ونصرةِ الحقِّ محمودة؛ فاجعل ما تملكه من قوّةٍ ومالٍ وأسبابٍ في طاعةِ الله ونفعِ دينه وعباده؛ فنعمُ الله أماناتٌ تُستعمَل في مرضاته؛ فمن سخّر نعمَ الله في طاعتِه بورك له فيها؛ فالخيلُ وكلُّ عُدّةٍ خيرٌ إذا صُرِفت في سبيلِ الله؛ فاتّخذ العُدّةَ، واجعل غايتها طاعةَ الله ونصرةَ دينه."}},{"n":32,"reflection":{"text":"«فقال إني أحببت حب الخير عن ذكر ربي حتى توارت بالحجاب» — فقال سليمانُ: إني أحببتُ حبَّ الخيلِ (الخير) لأجلِ ذكرِ ربي وجهادِ عدوّه، حتى غابت الشمسُ بالحجاب (أو: شُغِل بها عن الذكرِ فتداركها)؛ ففي هذا حرصُ سليمانَ على ألا يشغله شيءٌ عن ذكرِ الله؛ فاحذر أن تشغلك محابُّ الدنيا عن ذكرِ الله وطاعته، بل اجعل حبَّك لها تابعًا لطاعةِ الله، فلا تدع شيئًا يصرفك عن ذكرِ ربك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من أن تشغلَ محابُّ الدنيا عن ذكرِ الله."},"action":{"text":"تأمّل قولَ سليمانَ حين عُرِضت عليه الخيلُ حتى غابت الشمس: إني أحببتُ حبَّ الخيرِ — وهي الخيلُ — لأجلِ ذكرِ ربي والجهادِ في سبيله «فقال إني أحببت حب الخير عن ذكر ربي حتى توارت بالحجاب»؛ وفي معناه أنّ حبَّه لها كان لطاعةِ الله لا لهوى النفس؛ وقيل: شُغِل بعرضها عن وردٍ من ذكرِ الله حتى غابت الشمسُ فتداركه؛ ففي القصّةِ حرصُ سليمانَ على ألا يشغله شيءٌ من الدنيا عن ذكرِ الله وطاعته؛ فاحذر أن تشغلك محابُّ الدنيا — مالٌ أو ولدٌ أو تجارةٌ أو متاع — عن ذكرِ الله وطاعتِه وواجباتِ دينك؛ يا أيها الذين آمنوا لا تلهكم أموالكم ولا أولادكم عن ذكرِ الله؛ فاجعل حبَّك لما تحبُّ من الدنيا تابعًا لطاعةِ الله ومرضاته، لا مقدّمًا عليها؛ فإن أحببت شيئًا من متاعِ الدنيا فأحبَّه لتستعين به على طاعةِ الله؛ ولا تدع شيئًا يصرفك عن ذكرِ ربك وأداءِ فرائضه؛ فمن قدّم محابَّ الدنيا على ذكرِ الله خسر، ومن جعلها عونًا على طاعتِه ربح؛ فراقب قلبك: ألا يغلبه حبُّ الدنيا على حبِّ الله وذكره."}},{"n":33,"reflection":{"text":"«ردوها علي فطفق مسحا بالسوق والأعناق» — قال سليمانُ: ردّوا الخيلَ عليّ، فأخذ يمسح سوقها وأعناقها (كرامةً لها لأنها في سبيلِ الله، أو ذبحها قربةً لله لمّا شغلته عن الذكر)؛ ففي هذا إيثارُ سليمانَ طاعةَ الله على محبوبه؛ فقدّم طاعةَ الله ومرضاته على محابّك، وإذا شغلك شيءٌ عن الله فجاهد نفسك فيه، فإيثارُ الله على المحبوبِ من كمالِ العبودية.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إيثارُ طاعةِ الله على المحبوب، ومجاهدةُ ما يشغل عنه."},"action":{"text":"تأمّل موقفَ سليمانَ حين شغلته الخيلُ (على أحدِ التفسيرين) عن ذكرِ ربه: قال ردّوها عليّ، فأخذ يمسح بسيفِه سوقها وأعناقها فذبحها قربةً لله؛ أو أخذ يمسحها كرامةً لها لأنها معدّةٌ لسبيلِ الله «ردوها علي فطفق مسحا بالسوق والأعناق»؛ فعلى تفسيرِ الذبحِ آثر سليمانُ طاعةَ الله ومرضاته على محبوبه من الخيل، لمّا خشي أن تشغله؛ ففي هذا إيثارُ العبدِ طاعةَ الله على أحبِّ الأشياءِ إليه؛ فقدّم طاعةَ الله ومرضاته على محابّك ومشتهياتك؛ وإذا وجدت شيئًا يشغلك عن الله وطاعتِه فجاهد نفسك فيه، وقدّم حقَّ الله عليه؛ فإيثارُ الله على المحبوباتِ من كمالِ العبوديةِ والمحبّة؛ فما آثر عبدٌ رضا الله على هواه إلا عوّضه الله خيرًا؛ فمن ترك شيئًا لله عوّضه الله خيرًا منه؛ فراقب محابّك: إن زاحمت طاعةَ الله فقدّم طاعتَه؛ فالمؤمنُ الصادقُ يقدّم محبّةَ الله على كلِّ محبوب؛ فاجعل رضا الله فوق كلِّ شيء؛ فبإيثارِه تُنال المحبّةُ والقربُ والعوض."}},{"n":34,"reflection":{"text":"«ولقد فتنا سليمان وألقينا على كرسيه جسدا ثم أناب» — ولقد اختبرنا سليمانَ وألقينا على كرسيّه جسدًا (ابتلاءً)، ثم رجع إلى الله بالتوبةِ والإنابة؛ ففي هذا ابتلاءُ الله لأنبيائه وسرعةُ أوبتهم؛ فاعلم أنّ الابتلاءَ يصيب الصالحين، والعبرةُ بالأوبةِ إلى الله بعده، فإذا ابتُليت فأنب إلى الله، فالمؤمنُ يرجع إلى ربه في كلِّ حال.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الأوبةُ إلى الله بعد الابتلاء، وإدراكُ أنه يصيب الصالحين."},"action":{"text":"اعلم أنّ الله ابتلى نبيَّه سليمانَ واختبره، وألقى على كرسيّه جسدًا في قصّةٍ من قصصِ الابتلاء، ثم رجع سليمانُ إلى الله بالتوبةِ والإنابةِ والأوبة «ولقد فتنا سليمان وألقينا على كرسيه جسدا ثم أناب»؛ ففي هذا أنّ الابتلاءَ والفتنةَ تصيب حتى الأنبياءَ والصالحين، حكمةً من الله وتمحيصًا ورفعةً؛ فالعبرةُ ليست في وقوعِ الابتلاء، بل في الأوبةِ إلى الله بعده؛ فاعلم أنّ الابتلاءَ سنّةُ الله في عباده، يصيب الصالحين قبل غيرهم؛ فإذا ابتُليت بشيءٍ فأنب إلى الله، وارجع إليه بالتوبةِ والدعاءِ والتسليم؛ فالمؤمنُ يرجع إلى ربه في السرّاءِ والضرّاء، وفي البلاءِ والعافية؛ فلا يُقنّطك الابتلاءُ من رحمةِ الله، ولا يحملك على السخطِ والجزع؛ بل اجعله بابًا للأوبةِ والإنابةِ والقربِ من الله؛ فمن أناب إلى الله بعد الابتلاءِ رفعه الله وقرّبه؛ فكن أوّابًا منيبًا في كلِّ حال؛ فالأوبةُ إلى الله عزُّ العبدِ وسعادته."}},{"n":35,"reflection":{"text":"«قال رب اغفر لي وهب لي ملكا لا ينبغي لأحد من بعدي إنك أنت الوهاب» — قال سليمانُ: ربِّ اغفر لي، وأعطني مُلكًا لا يكون لأحدٍ بعدي، إنك أنت كثيرُ العطاء؛ ففي هذا بدؤه بالاستغفارِ ثم سؤالِ الله من فضله؛ فابدأ دعاءك بالاستغفارِ والتوبة، ثم اسأل الله من فضله، وأخلص سؤالك لله الوهّاب، فمن قدّم التوبةَ استجيب دعاؤه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"البدءُ بالاستغفار، ثم سؤالُ الله من فضلِه الواسع."},"action":{"text":"تأمّل دعاءَ سليمانَ حين أناب: بدأ بالاستغفارِ فقال: ربِّ اغفر لي، ثم سأل الله مُلكًا خاصًّا لا يكون لأحدٍ من بعده معجزةً له، معترفًا بأنّ الله هو الوهّابُ كثيرُ العطاء «قال رب اغفر لي وهب لي ملكا لا ينبغي لأحد من بعدي إنك أنت الوهاب»؛ فقدّم الاستغفارَ والتوبةَ على سؤالِ حاجته، وختم بالثناءِ على الله بالوهّاب؛ فابدأ دعاءك بالاستغفارِ والتوبةِ والثناءِ على الله؛ ثم اسأله حاجتك من فضله؛ فتقديمُ الاستغفارِ والثناءِ من أسبابِ إجابةِ الدعاء؛ وأخلص سؤالك لله وحده، فهو الوهّابُ الذي لا ينفد عطاؤه؛ فلا تسأل إلا الله، ولا ترجُ إلا فضله؛ فمن قدّم التوبةَ والاستغفارَ ثم دعا كان أرجى لإجابته؛ ولا حرج أن تسأل الله من واسعِ فضله ما شئت من خيرِ الدنيا والآخرة؛ فخزائنه ملأى لا تغيضها النفقة؛ فألحّ على الله في الدعاء، وابدأه بالاستغفارِ والثناء، واختمه بالتوسّلِ بأسمائه الحسنى؛ فالوهّابُ يعطي من سأله بأدبٍ ورجاء؛ فتأدّب في دعائك، وأخلصه لله، وأحسن الظنَّ بعطائه."}},{"n":36,"reflection":{"text":"«فسخرنا له الريح تجري بأمره رخاء حيث أصاب» — فسخّرنا لسليمانَ الريحَ تجري بأمره ليّنةً حيث قصد وأراد؛ ففي هذا إجابةُ دعائه وتمامُ فضلِ الله عليه؛ فاعلم أنّ الله يسخّر لعباده ما يشاء بفضله، فاسأل الله من فضله وثق بقدرته، فمن أخلص لله وأناب إليه سخّر الله له أسبابَ الخير.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بقدرةِ الله وفضلِه، وسؤالُه تسخيرَ أسبابِ الخير."},"action":{"text":"اعلم أنّ الله أجاب دعاءَ سليمانَ فسخّر له الريحَ تجري بأمره ليّنةً طيّعةً حيث أراد وقصد، تحمله ومُلكه «فسخرنا له الريح تجري بأمره رخاء حيث أصاب»؛ فهذا من تمامِ فضلِ الله على سليمانَ وإجابةِ دعائه؛ فاعلم أنّ الله يسخّر لعباده ما يشاء من مخلوقاتِه بفضله وقدرته؛ فالريحُ العاصفةُ القويّةُ تنقاد لأمرِ الله ليّنةً طيّعةً لعبده سليمان؛ فما أعظمَ قدرةَ الله وفضله؛ فاسأل الله من فضله، وثق بقدرتِه على كلِّ شيء؛ فهو القادرُ على أن يسخّر لك أسبابَ الخيرِ والتيسير؛ فمن أخلص لله وأناب إليه وتوكّل عليه سخّر الله له من الأسبابِ ما يعينه؛ فلا تيأس من فضلِ الله وتيسيره؛ واطلب منه أن ييسّر أمورك ويسخّر لك أسبابَ الخير؛ فبيدِ الله ملكوتُ كلِّ شيء؛ فاعتمد عليه، واطلب فضله، وأحسن الظنَّ بقدرته وكرمه؛ فمن توكّل على الله كفاه وسخّر له ما ينفعه."}},{"n":37,"reflection":{"text":"«والشياطين كل بناء وغواص» — وسخّرنا له الشياطينَ يعملون له، منهم البنّاؤون للأبنيةِ العظيمة، والغوّاصون في البحرِ يستخرجون اللآلئ؛ ففي هذا تمامُ التسخيرِ وعظمةُ قدرةِ الله؛ فاعلم أنّ الله على كلِّ شيءٍ قدير، يسخّر أعتى المخلوقاتِ لمن يشاء، فعظّم قدرةَ الله، وثق بأنه القادرُ على تسخيرِ كلِّ شيءٍ لعبده المؤمن.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ قدرةِ الله الذي يسخّر أعتى المخلوقات."},"action":{"text":"اعلم أنّ الله سخّر لسليمانَ الشياطينَ يعملون له بأمره: منهم البنّاؤون الذين يبنون له الأبنيةَ العظيمةَ والمحاريبَ والتماثيل، والغوّاصون في أعماقِ البحارِ يستخرجون له اللآلئ والجواهر «والشياطين كل بناء وغواص»؛ ففي هذا تمامُ التسخيرِ وعظمةُ قدرةِ الله؛ فالشياطينُ المتمرّدةُ العاتيةُ تنقاد لأمرِ الله وتعمل لعبدِه سليمان؛ فاعلم أنّ الله على كلِّ شيءٍ قدير، يسخّر أعتى المخلوقاتِ وأقواها لمن يشاء من عباده؛ فمن كان له مثلُ هذا المُلكِ العظيمِ وسخّرت له الشياطينُ والريحُ، فهو دليلٌ على عظمةِ قدرةِ الله ومُلكه؛ فعظّم قدرةَ الله في قلبك؛ وثق بأنه القادرُ على تسخيرِ كلِّ شيءٍ لعبدِه المؤمن؛ فلا تخف من الشياطينِ وشرورها ما دمت معتصمًا بالله؛ فالله قاهرٌ فوق عباده، مسخّرٌ لهم بأمره؛ فالجأ إلى الله القادرِ على كلِّ شيء؛ واستعذ به من شرِّ الشياطين؛ فمن اعتصم بالله عصمه، وسخّر له الأسباب، وكفاه شرَّ كلِّ ذي شر."}},{"n":38,"reflection":{"text":"«وآخرين مقرنين في الأصفاد» — وآخرين من الشياطينِ المردةِ مقيّدين في القيودِ والأغلال (كفًّا لشرّهم)؛ ففي هذا كمالُ تسخيرِ الله لسليمان؛ فاعلم أنّ الله يكفّ شرَّ المفسدين بقدرته، فاستعذ بالله من شرِّ كلِّ ذي شر، فمن استعاذ بالله كفاه شرَّ الأشرارِ وقيّد عنه أذاهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعاذةُ بالله من شرِّ الأشرار، فهو الكافُّ لشرّهم."},"action":{"text":"اعلم أنّ الله من تمامِ تسخيرِه لسليمانَ قيّد له آخرين من الشياطينِ المردةِ المفسدين في القيودِ والأغلال، كفًّا لشرّهم عن الناس «وآخرين مقرنين في الأصفاد»؛ فمن أطاعه من الشياطينِ استعمله، ومن تمرّد وأفسد قيّده وكفّ شرّه؛ ففي هذا كمالُ قدرةِ الله وتسخيرِه؛ فاعلم أنّ الله قادرٌ على أن يكفّ شرَّ المفسدين والأشرارِ بقدرته، ويقيّد عن عباده أذاهم؛ فالجأ إلى الله واستعذ به من شرِّ كلِّ ذي شر؛ فأعوذ بكلماتِ الله التامّاتِ من شرِّ ما خلق؛ فمن استعاذ بالله بصدقٍ كفاه شرَّ الأشرارِ والشياطين؛ فالله هو الحافظُ الكافي الذي يقيّد شرَّ المؤذين عن عباده المتوكّلين عليه؛ فلا تخف من شرِّ الأشرارِ ما دمت معتصمًا بالله؛ فأكثر من الأذكارِ والتعوّذاتِ الشرعية؛ فبها تُحفَظ من شرِّ الشياطينِ والأشرار؛ فمن كان الله حافظه لم يضرّه أحد؛ فاعتصم بالله، واستعذ به، وثق بحفظه وكفايته."}},{"n":39,"reflection":{"text":"«هذا عطاؤنا فامنن أو أمسك بغير حساب» — هذا عطاؤنا لك يا سليمانُ، فأعطِ من شئت وامنع من شئت، لا حسابَ عليك فيه؛ ففي هذا تفويضُ الله لسليمانَ في العطاءِ من فضله؛ فاعلم أنّ ما آتاك الله فضلٌ منه، فأنفقه في الخيرِ بسخاء، فمن أعطاه الله فليعطِ، والعطاءُ في سبيلِ الله لا ينقص المال، بل يبارك فيه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإنفاقُ من فضلِ الله بسخاء، وإدراكُ أنه عطاءٌ منه."},"action":{"text":"اعلم أنّ الله فوّض سليمانَ في مُلكِه وعطائه، فقال له: هذا عطاؤنا وفضلنا عليك، فأعطِ من شئت وامنع من شئت، لا حسابَ عليك ولا تبعة، فأنت مؤيّدٌ مسدّد «هذا عطاؤنا فامنن أو أمسك بغير حساب»؛ ففي هذا بيانُ أنّ ما آتاه الله سليمانَ فضلٌ ومنّةٌ منه؛ فاعلم أنّ ما آتاك الله من مالٍ أو جاهٍ أو قوّةٍ فضلٌ منه ونعمة؛ فأنفقه في وجوهِ الخيرِ والبرِّ بسخاءٍ وطيبِ نفس؛ فمن وسّع الله عليه فليوسّع على عباده؛ وأنفقوا ممّا رزقناكم؛ فالعطاءُ في سبيلِ الله لا ينقص المال، بل يبارك فيه ويزيده؛ ما نقصت صدقةٌ من مال؛ فأعطِ المحتاجين، وصِل الأرحام، وأنفق في وجوهِ الخير؛ واعلم أنّ ما تنفقه يُخلِفه الله ويضاعفه؛ فكن سخيًّا كريمًا بما آتاك الله؛ فالسخيُّ قريبٌ من الله ومن الناسِ ومن الجنّة؛ فاجعل مالك وسيلةً للقربِ من الله بالإنفاقِ والبذل؛ فما عند الله خيرٌ وأبقى؛ فأنفق ممّا آتاك الله، ولا تخش من ذي العرشِ إقلالًا."}},{"n":40,"reflection":{"text":"«وإن له عندنا لزلفى وحسن مآب» — وإنّ لسليمانَ عندنا لقربةً ومنزلةً رفيعةً وحسنَ مرجع؛ ففي هذا بيانُ منزلةِ سليمانَ عند الله مع مُلكه العظيم؛ فاعلم أنّ المُلكَ والمالَ لا يبعدان عن الله إذا صحبهما الإيمانُ والأوبة، فاجعل ما آتاك الله وسيلةً للقربِ منه، فالغنيُّ الشاكرُ الأوّابُ له عند الله زلفى.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"جعلُ نعمِ الدنيا وسيلةً للقربِ من الله بالشكرِ والأوبة."},"action":{"text":"اعلم أنّ الله بيّن أنّ لسليمانَ — مع مُلكِه العظيمِ الذي لا ينبغي لأحدٍ من بعده — عنده قربةً ومنزلةً رفيعةً وحسنَ مرجعٍ ومآب «وإن له عندنا لزلفى وحسن مآب»؛ ففي هذا أنّ المُلكَ والمالَ والنعمَ لا تبعد صاحبها عن الله إذا صحبها الإيمانُ والشكرُ والأوبةُ إليه؛ فسليمانُ آتاه الله مُلكًا عظيمًا، ومع ذلك كان أوّابًا شاكرًا قريبًا من الله؛ فاعلم أنّ الغنى والمُلكَ ليسا مانعينِ من القربِ من الله إذا استُعمِلا في طاعته وشُكِرت نعمتهما؛ فاجعل ما آتاك الله من نعمٍ وسيلةً للقربِ منه، لا سببًا للبعدِ عنه؛ فاشكر النعمَ، واستعملها في طاعةِ الله، وكن أوّابًا رجّاعًا إليه؛ فالغنيُّ الشاكرُ الأوّابُ له عند الله زلفى ومنزلةٌ رفيعة؛ فلا تجعل نعمَ الدنيا تشغلك عن الله؛ بل اجعلها معينةً لك على طاعته وقربه؛ فمن شكر النعمةَ وأدّى حقّها واستعملها في طاعةِ الله قرّبته إلى الله ورفعت منزلته؛ فاجمع بين نعمةِ الدنيا وحسنِ استعمالها، تنل زلفى الله وحسنَ مآبه."}},{"n":41,"reflection":{"text":"«واذكر عبدنا أيوب إذ نادى ربه أني مسني الشيطان بنصب وعذاب» — واذكر عبدنا أيوبَ حين نادى ربه: إنّ الشيطانَ مسّني بتعبٍ وألمٍ ومشقّة (في بدنه وأهلِه ومالِه)؛ ففي هذا التأسّي بصبرِ أيوبَ ولجوئه إلى الله في البلاء؛ فإذا نزل بك بلاءٌ فالجأ إلى الله واشكُ إليه، فأيوبُ شكا إلى الله لا إلى الخلق، فاجعل شكواك إلى الله وحده، فهو كاشفُ الضرّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اللجوءُ إلى الله والشكوى إليه وحده عند البلاء."},"action":{"text":"اعلم أنّ الله أمر نبيَّه أن يتذكّر عبدَه أيوبَ حين ابتلاه في بدنه وأهلِه ومالِه، فنادى ربه شاكيًا إليه: إنّ الشيطانَ مسّني بتعبٍ وألمٍ ومشقّةٍ وعذاب «واذكر عبدنا أيوب إذ نادى ربه أني مسني الشيطان بنصب وعذاب»؛ فتأمّل كيف لجأ أيوبُ إلى الله وشكا إليه بلاءه، مع صبرِه الجميل؛ ففي هذا التأسّي بصبرِ أيوبَ ولجوئه إلى الله في البلاء؛ فإذا نزل بك بلاءٌ — مرضٌ أو فقدٌ أو ضيق — فالجأ إلى الله واشكُ حالك إليه وحده؛ فأيوبُ شكا إلى الله لا إلى الخلق، وسمّاه الله صابرًا مع شكواه إليه؛ فالشكوى إلى الله لا تنافي الصبر؛ فاجعل شكواك وبثّك وحزنك إلى الله وحده؛ إنما أشكو بثّي وحزني إلى الله؛ فهو وحده كاشفُ الضرِّ والبلاء؛ فلا تشكُ الله إلى خلقه؛ بل اشكُ إلى الله، وألحّ عليه بالدعاء، واصبر محتسبًا؛ فمن لجأ إلى الله في بلائه كشفه عنه؛ فاجعل الله ملجأك وحده عند الشدائد؛ فبالدعاءِ والصبرِ يُكشَف البلاء."}},{"n":42,"reflection":{"text":"«اركض برجلك هذا مغتسل بارد وشراب» — قلنا له: اضرب الأرضَ برجلك، فنبعت عينٌ، هذا ماءٌ باردٌ تغتسل به وتشرب منه فيُشفى بدنك؛ ففي هذا سرعةُ فرجِ الله بعد الصبرِ والدعاء؛ فاعلم أنّ فرجَ الله يأتي بأسبابٍ يسيرة، فاصبر وادعُ، فبعد الضيقِ فرج، ومن صبر على البلاءِ ودعا كشفه الله عنه بأيسرِ الأسباب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرجاءُ في فرجِ الله بعد الصبرِ والدعاء، ولو بأيسرِ سبب."},"action":{"text":"تأمّل كيف فرّج الله عن أيوبَ بعد صبره ودعائه: أمره أن يضرب الأرضَ برجله، فنبعت له عينُ ماءٍ باردٍ يغتسل بها فيبرأ ظاهرُ بدنه، ويشرب منها فيبرأ باطنه «اركض برجلك هذا مغتسل بارد وشراب»؛ ففي هذا سرعةُ فرجِ الله بعد الصبرِ والدعاء، وأنه يأتي بأسبابٍ يسيرةٍ سهلة؛ فاعلم أنّ فرجَ الله قريب، يأتي بأيسرِ الأسبابِ وأهونها؛ فبعد الضيقِ فرج، وبعد العسرِ يسر؛ فاصبر على البلاءِ، وألحّ على الله بالدعاء؛ فمن صبر على بلائه ودعا ربه كشفه الله عنه في أحسنِ وقتٍ وبأيسرِ سبب؛ فلا تيأس من فرجِ الله ولو طال البلاء؛ فإنّ مع العسرِ يسرًا؛ فأحسن الظنَّ بالله، وانتظر فرجه؛ فقد يأتي الفرجُ من حيث لا تحتسب، وبسببٍ لا تتوقّعه؛ فما على العبدِ إلا الصبرُ والدعاءُ وحسنُ الظنِّ بالله، والله يتولّى الفرجَ بحكمته ورحمته؛ فاصبر وادعُ وارجُ، فإنّ فرجَ الله آتٍ لا محالة؛ فمن لزم الصبرَ والدعاءَ رأى فرجَ الله ولطفه."}},{"n":43,"reflection":{"text":"«ووهبنا له أهله ومثلهم معهم رحمة منا وذكرى لأولي الألباب» — ووهبنا لأيوبَ أهله الذين فقدهم ومثلهم معهم، رحمةً منا وعبرةً لأصحابِ العقول؛ ففي هذا تعويضُ الله للصابرين بأحسنَ ممّا فقدوا؛ فاعلم أنّ الله يعوّض الصابرين خيرًا ممّا فقدوا، فاصبر على المصائبِ راجيًا عوضَ الله، فمن صبر واحتسب عوّضه الله وزاده.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ على المصائبِ رجاءَ عوضِ الله وزيادتِه."},"action":{"text":"اعلم أنّ الله عوّض أيوبَ بعد صبره على البلاء، فوهب له أهله الذين فقدهم ومثلهم معهم زيادةً، رحمةً منه وعبرةً لأصحابِ العقولِ السليمة «ووهبنا له أهله ومثلهم معهم رحمة منا وذكرى لأولي الألباب»؛ ففي هذا أنّ الله يعوّض الصابرين المحتسبين بأحسنَ ممّا فقدوا وأكثر؛ فاعلم أنّ من صبر على المصيبةِ واحتسب عوّضه الله خيرًا منها؛ فما ترك عبدٌ شيئًا لله أو صبر على فقدِ محبوبٍ إلا عوّضه الله خيرًا؛ فاصبر على المصائبِ والفقدِ راجيًا عوضَ الله وثوابه؛ ولا تجزع ولا تسخط؛ فإنّ الجزعَ لا يردّ المصيبةَ ويحبط الأجر؛ بل الصبرُ يجلب العوضَ والثواب؛ فمن صبر واحتسب عند المصيبةِ أخلف الله له خيرًا منها؛ فاجعل شعارك عند المصائب: إنا لله وإنا إليه راجعون، اللهم أجرني في مصيبتي وأخلف لي خيرًا منها؛ فمن قالها صادقًا أخلف الله له؛ فالصبرُ على البلاءِ سبيلُ العوضِ والثواب؛ فاصبر، واحتسب، وارجُ عوضَ الله؛ فإنه لا يضيع أجرَ الصابرين، بل يوفّيهم أجرهم بغيرِ حساب."}},{"n":44,"reflection":{"text":"«وخذ بيدك ضغثا فاضرب به ولا تحنث إنا وجدناه صابرا نعم العبد إنه أواب» — وقلنا لأيوب: خذ حزمةً من عيدانٍ فاضرب بها (زوجتك برًّا بيمينك) ولا تحنث في قسمك؛ إنا وجدنا أيوبَ صابرًا، نِعم العبدُ، إنه أوّاب؛ ففي هذا تيسيرُ الله على عبده في برِّ يمينه، وثناؤه على صبرِ أيوب؛ فاصبر على البلاءِ كأيوب، وبرَّ بيمينك، واطلب المخارجَ الشرعيةَ عند الحرج، فالصبرُ خُلُقُ الأوّابين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ على البلاءِ كأيوب، والبرُّ باليمين، وطلبُ المخارجِ الشرعية."},"action":{"text":"تأمّل ختامَ قصّةِ أيوب: كان قد حلف في مرضه ليضربنّ زوجته عددًا (لأمرٍ غاضبته)، فلمّا شفاه الله رفق به وبها، فأمره أن يأخذ حزمةً من عيدانٍ فيضربها بها ضربةً واحدةً برًّا بيمينه ولا يحنث «وخذ بيدك ضغثا فاضرب به ولا تحنث إنا وجدناه صابرا نعم العبد إنه أواب»؛ ثم أثنى الله عليه: إنا وجدناه صابرًا، نِعم العبد، إنه أوّابٌ رجّاعٌ إلى الله؛ ففي هذا تيسيرُ الله على عبده مخرجًا شرعيًّا يبرّ به يمينه من غيرِ حرج، وثناؤه على صبرِ أيوب؛ فتعلّم من أيوبَ الصبرَ على البلاءِ حتى أثنى الله عليه بالصبر؛ فاصبر على بلائك كما صبر أيوب؛ وبرَّ بيمينك ووفِّ بعهدك؛ واطلب المخارجَ الشرعيةَ عند الحرجِ والضيق؛ فإنّ الله جعل مع العسرِ يسرًا، وشرع لعباده المخارجَ من الحرج؛ ومن يتّق الله يجعل له مخرجًا؛ فالصبرُ خُلُقُ الأوّابين، وثناءُ الله على أيوبَ بالصبرِ والأوبةِ يدلّ على فضلهما؛ فكن صابرًا أوّابًا، تنل ثناءَ الله ومحبّته؛ فنِعم العبدُ الصابرُ الأوّابُ إلى ربه."}}]}],"coverage":{"covered":44,"total":88}};
